head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.param1 = "";
scwin.flag = "";

// 기관 코드

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_2);
        scwin.flag = "0";
        txb_INST_NM.focus();
        const arrPar = new Array();
        const parentWin = $c.frame.path("../");
        const fn_GetPar = parentWin.fn_GetParam;
        if (fn_GetPar !== undefined) {
            fn_GetPar(arrPar);
            scwin.param1 = ((arrPar.length >= 1) && (arrPar[0] !== undefined) ? arrPar[0] : "");
            // alert(param1);
            if (scwin.param1 === "") return;
            await scwin.ins_search("", scwin.param1);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90100.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (row === 0) return;
        if (dts_List.getCellData(row, "STD_CD_INST_STAT_CD") !== '1') {
            await $c.win.alert('기관상태가 정상인 기관만 선택 가능 합니다.\n선택을 원할 경우 기관관리화면에서 상태를 변경 후 선택이 가능합니다.');
            return;
        }
        const BND_INST_CD = dts_List.getCellData(row, "BND_INST_CD");
        const INST_NM = dts_List.getCellData(row, "INST_NM");
        $c.frame.path("../").ins_popupRtn_cdnm(BND_INST_CD, INST_NM);
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90100.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90100.btn_close_onclick" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        scwin.flag = "1";
        await scwin.ins_search(txb_INST_NM.getValue());
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90100.btn_search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90100.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90100.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name txb_INST_NM_onkeyup
 * @description txb_INST_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_INST_NM_onkeyup = async function() {
    try {
        scwin.flag = "1";
        fn_DelChar(this);
        if (txb_INST_NM.getValue() === "") {

        } else {
            if (window.event.keyCode === 13) {
                await scwin.ins_search(txb_INST_NM.getValue());
            } else {

            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS90100.txb_INST_NM_onkeyup" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 기관 코드 조회한다.
 * @param {String} instNm instNm
 * @param {String} mktID mktID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function(instNm, mktID) {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
